  CONSTRAINT `forms_typeform_connection_id_foreign` FOREIGN KEY (`typeform_connection_id`) REFERENCES `typeform_connections` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
