--
-- Table structure for table `submissions`
--

DROP TABLE IF EXISTS `submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `submissions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `form_id` bigint unsigned NOT NULL,
  `form_version_id` bigint unsigned NOT NULL,
  `hospital_id` bigint unsigned NOT NULL,
  `branch_id` bigint unsigned DEFAULT NULL,
  `response_token` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `landed_at` timestamp NULL DEFAULT NULL,
  `is_partial` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('pending_review','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'approved',
  `source` enum('webhook','backfill','reconcile') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'webhook',
  `raw` json NOT NULL,
  `info` json DEFAULT NULL,
  `points` decimal(10,2) DEFAULT NULL,
  `max_points` decimal(10,2) DEFAULT NULL,
  `overall_pct` decimal(5,2) DEFAULT NULL,
  `rag` enum('green','amber','red') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
